      "arFull": "قُلْ مَنْ حَرَّمَ زِیْنَةَ اللّٰهِ الَّتِیْۤ اَخْرَجَ لِعِبَادِهٖ وَالطَّیِّبٰتِ مِنَ الرِّزْقِ ؕ قُلْ هِیَ لِلَّذِیْنَ اٰمَنُوْا فِی الْحَیٰوةِ الدُّنْیَا خَالِصَةً یَّوْمَ الْقِیٰمَةِ ؕ كَذٰلِكَ نُفَصِّلُ الْاٰیٰتِ لِقَوْمٍ یَّعْلَمُوْنَ ۟",
