      "arFull": "الَّذِیْنَ اتَّخَذُوْا دِیْنَهُمْ لَهْوًا وَّلَعِبًا وَّغَرَّتْهُمُ الْحَیٰوةُ الدُّنْیَا ۚ فَالْیَوْمَ نَنْسٰىهُمْ كَمَا نَسُوْا لِقَآءَ یَوْمِهِمْ هٰذَا ۙ وَمَا كَانُوْا بِاٰیٰتِنَا یَجْحَدُوْنَ ۟",
