      "arFull": "وَلَقَدْ جِئْنٰهُمْ بِكِتٰبٍ فَصَّلْنٰهُ عَلٰی عِلْمٍ هُدًی وَّرَحْمَةً لِّقَوْمٍ یُّؤْمِنُوْنَ ۟",
