      "arFull": "اِنَّكُمْ لَتَاْتُوْنَ الرِّجَالَ شَهْوَةً مِّنْ دُوْنِ النِّسَآءِ ؕ بَلْ اَنْتُمْ قَوْمٌ مُّسْرِفُوْنَ ۟",
