      "arFull": "فَتَوَلّٰی عَنْهُمْ وَقَالَ یٰقَوْمِ لَقَدْ اَبْلَغْتُكُمْ رِسٰلٰتِ رَبِّیْ وَنَصَحْتُ لَكُمْ ۚ فَكَیْفَ اٰسٰی عَلٰی قَوْمٍ كٰفِرِیْنَ ۟۠",
