      "arFull": "وَمَا وَجَدْنَا لِاَكْثَرِهِمْ مِّنْ عَهْدٍ ۚ وَاِنْ وَّجَدْنَاۤ اَكْثَرَهُمْ لَفٰسِقِیْنَ ۟",
