      "ur": "اور جب ان پر کوئی عذاب واقع ہوتا تو یوں کہتے کہ اے موسیٰ! ہمارے لیے اپنے رب سے اس بات کی دعا کر دیجئے! جس کا اس نے آپ سے عہد کر رکھا ہے، اگر آپ اس عذاب کو ہم سے ہٹا دیں تو ہم ضرور ضرور آپ کے کہنے سے ایمان لے آئیں گے اور ہم بنی اسرائیل کو بھی (رہا کر کے) آپ کے ہمراه کر دیں گے۔",
