      "arFull": "وَوٰعَدْنَا مُوْسٰی ثَلٰثِیْنَ لَیْلَةً وَّاَتْمَمْنٰهَا بِعَشْرٍ فَتَمَّ مِیْقَاتُ رَبِّهٖۤ اَرْبَعِیْنَ لَیْلَةً ۚ وَقَالَ مُوْسٰی لِاَخِیْهِ هٰرُوْنَ اخْلُفْنِیْ فِیْ قَوْمِیْ وَاَصْلِحْ وَلَا تَتَّبِعْ سَبِیْلَ الْمُفْسِدِیْنَ ۟",
      "ur": "اور ہم نے موسیٰ (علیہ السلام) سے تیس راتوں کا وعده کیا اور دس رات مزید سے ان تیس راتوں کو پورا کیا۔ سو ان کے پروردگار کا وقت پورے چالیس رات کا ہوگیا[1] ۔ اور موسیٰ (علیہ السلام) نے اپنے بھائی ہارون (علیہ السلام) سے کہا کہ میرے بعد ان کا انتظام رکھنا اور اصلاح کرتے رہنا اور بدنظم لوگوں کی رائے پر عمل مت کرنا۔[2]",
      "en": "And We made an appointment with Moses for thirty nights and perfected them by [the addition of] ten; so the term of his Lord was completed as forty nights. And Moses said to his brother Aaron, \"Take my place among my people, do right [by them],[400] and do not follow the way of the corrupters.\"",
