      "number": 151,
      "arFull": "قَالَ رَبِّ اغْفِرْ لِیْ وَلِاَخِیْ وَاَدْخِلْنَا فِیْ رَحْمَتِكَ ۖؗ وَاَنْتَ اَرْحَمُ الرّٰحِمِیْنَ ۟۠",
      "ur": "موسیٰ (علیہ السلام) نے کہا کہ اے میرے رب! میری خطا معاف فرما اور میرے بھائی کی بھی اور ہم دونوں کو اپنی رحمت میں داخل فرما اور تو سب رحم کرنے والوں سے زیاده رحم کرنے واﻻ ہے۔",
      "en": "[Moses] said, \"My Lord, forgive me and my brother and admit us into Your mercy, for You are the most merciful of the merciful.\"",
