      "arFull": "وَاكْتُبْ لَنَا فِیْ هٰذِهِ الدُّنْیَا حَسَنَةً وَّفِی الْاٰخِرَةِ اِنَّا هُدْنَاۤ اِلَیْكَ ؕ قَالَ عَذَابِیْۤ اُصِیْبُ بِهٖ مَنْ اَشَآءُ ۚ وَرَحْمَتِیْ وَسِعَتْ كُلَّ شَیْءٍ ؕ فَسَاَكْتُبُهَا لِلَّذِیْنَ یَتَّقُوْنَ وَیُؤْتُوْنَ الزَّكٰوةَ وَالَّذِیْنَ هُمْ بِاٰیٰتِنَا یُؤْمِنُوْنَ ۟ۚ",
      "ur": "اور ہم لوگوں کے نام دنیا میں بھی نیک حالی لکھ دے اور آخرت میں بھی، ہم تیری طرف رجوع کرتے ہیں[1] ۔ اللہ تعالیٰ نے فرمایا کہ میں اپنا عذاب اسی پر واقع کرتا ہوں جس پر چاہتا ہوں اور میری رحمت تمام اشیا پر محیط ہے[2]۔ تو وه رحمت ان لوگوں کے نام ضرور لکھوں گا جو اللہ سے ڈرتے ہیں اور زکوٰة دیتے ہیں اور جو ہماری آیتوں پر ایمان ﻻتے ہیں۔",
      "en": "And decree for us in this world [that which is] good and [also] in the Hereafter; indeed, we have turned back to You.\" [Allāh] said, \"My punishment - I afflict with it whom I will, but My mercy encompasses all things.\" So I will decree it [especially] for those who fear Me and give zakāh and those who believe in Our verses-",
