      "arFull": "وَاِذْ تَاَذَّنَ رَبُّكَ لَیَبْعَثَنَّ عَلَیْهِمْ اِلٰی یَوْمِ الْقِیٰمَةِ مَنْ یَّسُوْمُهُمْ سُوْٓءَ الْعَذَابِ ؕ اِنَّ رَبَّكَ لَسَرِیْعُ الْعِقَابِ ۖۚ وَاِنَّهٗ لَغَفُوْرٌ رَّحِیْمٌ ۟",
