      "number": 168,
      "arFull": "وَقَطَّعْنٰهُمْ فِی الْاَرْضِ اُمَمًا ۚ مِنْهُمُ الصّٰلِحُوْنَ وَمِنْهُمْ دُوْنَ ذٰلِكَ ؗ وَبَلَوْنٰهُمْ بِالْحَسَنٰتِ وَالسَّیِّاٰتِ لَعَلَّهُمْ یَرْجِعُوْنَ ۟",
      "ur": "اور ہم نے دنیا میں ان کی مختلف جماعتیں کر دیں۔ بعض ان میں نیک تھے اور بعض ان میں اور طرح تھے اور ہم ان کو خوش حالیوں اور بدحالیوں سے آزماتے رہے کہ شاید باز آجائیں۔[1]",
      "en": "And We divided them throughout the earth into nations. Of them some were righteous, and of them some were otherwise. And We tested them with good [times] and bad that perhaps they would return [to obedience].",
