      "arFull": "وَلَوْ شِئْنَا لَرَفَعْنٰهُ بِهَا وَلٰكِنَّهٗۤ اَخْلَدَ اِلَی الْاَرْضِ وَاتَّبَعَ هَوٰىهُ ۚ فَمَثَلُهٗ كَمَثَلِ الْكَلْبِ ۚ اِنْ تَحْمِلْ عَلَیْهِ یَلْهَثْ اَوْ تَتْرُكْهُ یَلْهَثْ ؕ ذٰلِكَ مَثَلُ الْقَوْمِ الَّذِیْنَ كَذَّبُوْا بِاٰیٰتِنَا ۚ فَاقْصُصِ الْقَصَصَ لَعَلَّهُمْ یَتَفَكَّرُوْنَ ۟",
