      "number": 177,
      "arFull": "سَآءَ مَثَلَا لْقَوْمُ الَّذِیْنَ كَذَّبُوْا بِاٰیٰتِنَا وَاَنْفُسَهُمْ كَانُوْا یَظْلِمُوْنَ ۟",
