      "arFull": "مَنْ یَّهْدِ اللّٰهُ فَهُوَ الْمُهْتَدِیْ ۚ وَمَنْ یُّضْلِلْ فَاُولٰٓىِٕكَ هُمُ الْخٰسِرُوْنَ ۟",
