      "arFull": "وَاِمَّا یَنْزَغَنَّكَ مِنَ الشَّیْطٰنِ نَزْغٌ فَاسْتَعِذْ بِاللّٰهِ ؕ اِنَّهٗ سَمِیْعٌ عَلِیْمٌ ۟",
