      "arFull": "اِنَّ الَّذِیْنَ اتَّقَوْا اِذَا مَسَّهُمْ طٰٓىِٕفٌ مِّنَ الشَّیْطٰنِ تَذَكَّرُوْا فَاِذَا هُمْ مُّبْصِرُوْنَ ۟ۚ",
